const menus={services,productions:[['productions','Productions'],['live-events','Live Events'],['private-meetings','Private Meetings']],process:[['discover','01 Discover'],['develop','02 Develop'],['prepare','03 Prepare'],['produce','04 Produce'],['finish','05 Finish'],['deliver','06 Deliver']],team:[['team','Our Team'],['ceo-biography','CEO Biography'],['administrative','Administrative'],['key-members','Key / Reach Members']],story:[['story','Story Home'],['novels','Our Novels'],['songs','Our Songs'],['tutorials','Our Tutorials'],['have-a-story','Have a Story']]};
const cover=['https://images.unsplash.com/photo-1485846234645-a62644f84728?auto=format&fit=crop&w=900&q=80','https://images.unsplash.com/photo-1586899028174-e7098604235b?auto=format&fit=crop&w=900&q=80','https://images.unsplash.com/photo-1598387993441-a364f854c3e1?auto=format&fit=crop&w=900&q=80'];const app=document.querySelector('#app');let counts={views:12914,downloads:1924,shares:882,comments:368,likes:2533};
function hero(e,t,d){return `<section class="page-hero"><div class="wrap reveal"><div class="eyebrow">${e}</div><h1 class="title">${t}</h1><p class="lead">${d}</p></div></section>`}function metric(){return `<span>Watch ${counts.views.toLocaleString()}</span><span>Download ${counts.downloads.toLocaleString()}</span><span>Share ${counts.shares.toLocaleString()}</span><span>Like ${counts.likes.toLocaleString()}</span><span>Subscribe 368</span>`}function card(s){return `<a class="service-card card reveal" href="#${s[0]}"><span class="number">${s[1].slice(0,2)}</span><div class="icon">${s[2]}</div><h3>${s[1].slice(3)}</h3><p>${s[3]}</p></a>`}function media(n=3){return Array.from({length:n},(_,i)=>`<article class="media-card card reveal"><div class="cover" style="background-image:url('${cover[i%3]}')"><span class="tag">${i?'FEATURE':'VIDEO'}</span></div><div class="media-body"><h3>${['Stories in motion','Studio sessions','Behind the frame'][i%3]}</h3><p>Watch the production, share it, or unlock a protected download.</p><div class="media-actions"><button class="button button-gold js-watch">Watch</button><button class="button button-outline js-download">Download</button><button class="button button-outline js-share">Share</button></div><div class="metrics">${metric()}</div></div></article>`).join('')}
function home(){return `<section class="hero"><div class="wrap hero-grid"><div class="reveal"><div class="eyebrow">Shoto Point Production</div><h1>We create <em>stories</em> that move.</h1><p>A production company shaping cinematic films, television, documentary, commercial and digital media experiences.</p><div class="hero-buttons"><a class="button button-gold" href="#register">Start a production</a><a class="button button-outline" href="#productions">View productions</a></div><div class="hero-stats"><span><b>120+</b><small>Productions</small></span><span><b>48+</b><small>Partners</small></span><span><b>8+</b><small>Years creating</small></span></div></div><div class="hero-card reveal"><img src="${cover[0]}" alt="Film camera on a production set"><div><button class="play js-watch">▶</button><span><b>CREATE</b><br><small>Your story starts here</small></span></div></div></div></section>`}
function service(id){let s=services.find(x=>x[0]===id)||services[0];return hero('Services',s[1].slice(3),s[3])+`<section class="content"><div class="wrap two-col"><article class="info-card card reveal"><div class="eyebrow">Our impact</div><h3>Made for the next audience.</h3><p class="lead">This service brings focused craft to projects that will inform, entertain and create opportunity long after release.</p><br><blockquote>“The team listened first, then made the message feel bigger than we imagined.” <small>— Production client</small></blockquote><br><a class="button button-gold" href="#register">Request this service</a></article><div>${media(1)}</div></div></section>`}
function productions(){return hero('Productions','Made to be watched, heard and shared.','A living archive of Shoto Point work. Stream via YouTube and unlock protected downloads after payment.')+`<section class="content"><div class="wrap"><div class="notice">Live counters update as viewers engage. Downloads are only released after verified payment.</div><div class="two-col"><article class="info-card card reveal"><div class="eyebrow">The future</div><h3>Stories that travel further.</h3><p class="lead">Our productions are designed to deepen conversations, grow talent and make Nigerian creative work visible to wider audiences.</p><br><blockquote>“The final film has given our campaign a lasting voice.” <small>— Partner testimonial</small></blockquote></article><article class="info-card card reveal"><div class="eyebrow">From the archive</div><h3>Past work, still moving.</h3><p class="lead">Explore earlier films, television features and creative sessions in the collection below.</p></article></div><br><div class="media-grid">${media()}</div></div></section>`}
function process(id){let names=['discover','develop','prepare','produce','finish','deliver'],n=names.indexOf(id);return hero('Our process',`${String(n+1).padStart(2,'0')} ${names[n][0].toUpperCase()+names[n].slice(1)}`,'A deliberate stage in taking a creative idea from first conversation to a finished release.')+`<section class="content"><div class="wrap two-col"><div class="info-card card reveal"><h3>What happens at this stage</h3><p class="lead">We work closely with the people behind the story, keep decisions clear, and make room for the craft that gives every production its identity.</p></div><div class="process">${names.map((x,i)=>`<a class="process-item ${x===id?'card':''}" href="#${x}"><span class="number">0${i+1}</span><b>${x[0].toUpperCase()+x.slice(1)}</b></a>`).join('')}</div></div></section>`}
function team(kind){return hero('The team',kind==='ceo-biography'?'Leadership with vision.':kind==='administrative'?'Administrative leadership.':'Senior production specialists.','Every team member has a live profile managed from the Shoto Point Control Centre.')+`<section class="content"><div class="wrap"><div id="dynamicTeam" class="grid"><div class="notice">Loading team profiles from the Admin Control Centre…</div></div></div></section>`}
async function registration(){return hero('Start a project','A registration form built around your next step.','Choose a project type and the form adapts to collect what the team needs.')+`<section class="content"><form class="registration card reveal" id="registration"><div class="registration-types">${['Film / TV production','Training or class','Podcast session','Photography','Talent & casting','Digital media'].map((x,i)=>`<label class="type-option"><input type="radio" name="type" value="${x}" ${i?'':'checked'}> ${x}</label>`).join('')}</div><div class="form-grid"><div class="field"><label>Full name</label><input required name="name" placeholder="Your full name"></div><div class="field"><label>Email address</label><input required type="email" name="email" placeholder="you@example.com"></div><div class="field"><label>Phone number</label><input required name="phone" placeholder="+234..."></div><div class="field"><label>Preferred start date</label><input type="date" name="date"></div><div class="field full"><label>Tell us about the project</label><textarea required name="details" placeholder="A short outline, audience, goals and approximate budget."></textarea></div></div><br><button class="button button-gold" type="submit">Submit registration</button></form></section>`}
function meetings(live){return hero(live?'Live Events':'Private Meetings',live?'Watch Shoto Point broadcasts without leaving this page.':'Request a Zoom, TeamViewer or Google Meet session and wait for Admin approval.',live?'Live video is embedded below. The Control Centre chooses the active stream.':'Meeting links are released only after Admin approval and code generation.')+`<section class="content"><div class="wrap"><div id="dynamicMeetings" class="meeting card reveal">Loading…</div></div></section>`}
function storyPage(r){let title=r==='novels'?'Novels & Stories':r==='songs'?'Songs — listen online':r==='tutorials'?'Tutorials':'Stories beyond the screen.';return hero('Story',title,'A distinct home for writing, music and learning from the Shoto Point community.')+`<section class="content"><div class="wrap"><div class="media-grid" id="dynamicStory"><div class="notice">Loading published Story content…</div></div></div></section>`}
async function hydrateDynamic(){
 const route=location.hash.slice(1)||'home';
 const esc2=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 if(['team','ceo-biography','administrative','key-members'].includes(route)){
  const box=document.querySelector('#dynamicTeam'); if(box) try{const g=route==='ceo-biography'?'ceo':route==='administrative'?'administrative':route==='key-members'?'senior':'';const r=await fetch('/api/public/team'+(g?'?group='+g:''));const rows=r.ok?(await r.json()).data||[]:[];box.innerHTML=rows.length?rows.map(x=>`<article class="person-card card reveal visible"><img src="${esc2(x.image_url||'assets/team-placeholder.jpg')}" alt="${esc2(x.name)}"><div><span class="role">${esc2(x.role)}</span><h3>${esc2(x.name)}</h3><p>${esc2(x.short_bio||'Shoto Point Production team member.')}</p><br><a class="button button-gold" href="team-member.html?id=${x.id}">Read More →</a></div></article>`).join(''):'<div class="notice">No active team profiles have been published yet.</div>';}catch(e){box.innerHTML='<div class="notice">Team service temporarily unavailable.</div>'}
 }
 if(route==='live-events'){
  const box=document.querySelector('#dynamicMeetings');if(box) try{const r=await fetch('/api/public/live-events');const rows=(await r.json()).data||[];box.innerHTML=rows.length?rows.map(x=>`<article class="live-embed"><span class="role">${esc2(x.provider)} · ${esc2(x.status)}</span><h3>${esc2(x.title)}</h3><div class="embed-frame"><iframe src="${esc2(x.embed_url)}" title="${esc2(x.title)}" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe></div><p>${esc2(x.description||'Live Shoto Point broadcast.')}</p></article>`).join(''):'<div class="notice">No live broadcast is currently configured. Admin can add YouTube or Facebook video embeds from Live Events.</div>';}catch(e){box.innerHTML='<div class="notice">Live events service temporarily unavailable.</div>'}
 }
 if(route==='private-meetings'){
  const box=document.querySelector('#dynamicMeetings');if(box) box.innerHTML=`<div class="meeting-grid"><article class="info-card"><span class="role">ZOOM</span><h3>Zoom Meeting</h3><p>Request access. Admin validates the request and generates the meeting code.</p><button class="button button-gold js-meeting" data-platform="Zoom">Request Zoom</button></article><article class="info-card"><span class="role">TEAMVIEWER</span><h3>TeamViewer</h3><p>Request an approved remote session code from the Control Centre.</p><button class="button button-gold js-meeting" data-platform="TeamViewer">Request TeamViewer</button></article><article class="info-card"><span class="role">GOOGLE MEET</span><h3>Google Meet</h3><p>Request a Google Meet invitation and receive it after Admin validation.</p><button class="button button-gold js-meeting" data-platform="Google Meet">Request Google Meet</button></article><article class="info-card"><span class="role">SHOTO ROOM</span><h3>Inside the Shoto Room</h3><p>Approved participants can retrieve their generated meeting link and passcode here.</p><button class="button button-outline" onclick="const e=prompt('Enter the approved email address'); if(e) fetch('/api/public/meeting-links?email='+encodeURIComponent(e)).then(r=>r.json()).then(x=>alert(x.data?.length?x.data.map(m=>m.provider+': '+m.join_url+(m.passcode?' | Code: '+m.passcode:'')).join('\\n'):'No approved meeting found.'))">Get approved link</button></article></div>`;
 }
 if(['novels','songs','tutorials','story'].includes(route)){
  const box=document.querySelector('#dynamicStory');if(box) try{const r=await fetch('/api/content?section='+encodeURIComponent(route));const rows=(await r.json()).data||[];box.innerHTML=rows.length?rows.map(x=>{const audio=x.content_type==='audio';const action=audio?`<button class="button button-gold sp-play" data-url="${esc2(x.media_url)}">Listen</button>`:`<a class="button button-gold" href="content.html?id=${x.id}">Read More</a>`;return `<article class="media-card card reveal visible"><div class="cover" style="background-image:url('${esc2(x.media_url||'assets/team-placeholder.jpg')}')"><span class="tag">${esc2(x.content_type)}</span></div><div class="media-body"><h3>${esc2(x.title)}</h3><p>${esc2(x.description||'')}</p><div class="media-actions">${action}<button class="button button-outline sp-download" data-id="${x.id}">Download</button><button class="button button-outline sp-share" data-title="${esc2(x.title)}">Share</button></div></div></article>`}).join(''):'<div class="notice">No published content is available yet. Add it from Admin → Content Studio.</div>';}catch(e){box.innerHTML='<div class="notice">Content service temporarily unavailable.</div>'}
 }
 document.querySelectorAll('.sp-play').forEach(b=>b.onclick=()=>{const a=new Audio(b.dataset.url);a.play();b.textContent='Playing…';a.onended=()=>b.textContent='Listen'});
 document.querySelectorAll('.sp-share').forEach(b=>b.onclick=()=>openShareSheet(b.dataset.title,location.href));
 document.querySelectorAll('.sp-download').forEach(b=>b.onclick=()=>location.href='checkout.html?item='+encodeURIComponent(b.dataset.id));
}
function openShareSheet(title,url){const encoded=encodeURIComponent(url),text=encodeURIComponent(title);const m=document.createElement('div');m.className='modal open';m.innerHTML=`<div class="modal-panel"><button class="modal-close">×</button><h2 class="title">Share</h2><p class="lead">Choose where to share this item or copy its link.</p><div class="media-actions" style="flex-wrap:wrap;margin-top:20px"><a class="button button-outline" target="_blank" href="https://www.facebook.com/sharer/sharer.html?u=${encoded}">Facebook</a><a class="button button-outline" target="_blank" href="https://wa.me/?text=${text}%20${encoded}">WhatsApp</a><a class="button button-outline" target="_blank" href="https://twitter.com/intent/tweet?text=${text}&url=${encoded}">X</a><a class="button button-outline" target="_blank" href="https://t.me/share/url?url=${encoded}&text=${text}">Telegram</a><a class="button button-outline" href="mailto:?subject=${text}&body=${encoded}">Email</a><button class="button button-gold" id="copyShare">Copy link</button></div></div>`;document.body.appendChild(m);m.querySelector('.modal-close').onclick=()=>m.remove();m.querySelector('#copyShare').onclick=()=>navigator.clipboard.writeText(url).then(()=>{m.remove();document.querySelector('#toast')?.classList.add('show')})}
function render(){let r=location.hash.slice(1)||'home';let h=r==='home'?home():r==='services'?hero('Services','The full production studio.','Nine focused services, one creative partner.')+`<section class="content"><div class="wrap grid">${services.map(card).join('')}</div></section>`:services.some(x=>x[0]===r)?service(r):r==='productions'?productions():r==='live-events'?meetings(true):r==='private-meetings'?meetings(false):['discover','develop','prepare','produce','finish','deliver'].includes(r)?process(r):['team','ceo-biography','administrative','key-members'].includes(r)?team(r):['story','novels','songs','tutorials'].includes(r)?storyPage(r):r==='novel-reader'||r==='media-reader'?reader():r==='register'||r==='have-a-story'?registration():basic(r);app.innerHTML=h;document.title=`${r.replaceAll('-',' ').replace(/\b\w/g,x=>x.toUpperCase())} | Shoto Point`;observe();bind();hydrateDynamic();scrollTo({top:0,behavior:'smooth'})}
function openModal(h){document.querySelector('#modalContent').innerHTML=h;document.querySelector('#modal').classList.add('open')}function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)}function bind(){
 document.querySelectorAll('.js-watch').forEach(x=>x.onclick=()=>openModal(`<h2 class="title">Watch on YouTube</h2><p class="lead">This production opens from our YouTube viewing experience.</p><br><a class="button button-gold" href="https://www.youtube.com/" target="_blank" rel="noopener">Open YouTube ↗</a>`));
 document.querySelectorAll('.js-read').forEach(x=>x.onclick=()=>openModal(`<h2 class="title">Read the novel</h2><p class="lead">This reading view will open the selected novel chapter by chapter. The final text can be published from the admin centre.</p><br><button class="button button-gold">Start reading</button>`));
 document.querySelectorAll('.js-download').forEach(x=>x.onclick=()=>openModal(`<h2 class="title">Unlock download</h2><p class="lead">Downloads are protected. Complete payment to receive a time-limited secure link.</p><br><button class="button button-gold" id="pay">Continue to payment</button>`));
 document.querySelector('#pay')?.addEventListener('click',()=>{document.querySelector('#modal').classList.remove('open');toast('Open the checkout from the published item to continue with Paystack.')});
 document.querySelectorAll('.js-bio').forEach(x=>x.onclick=()=>openModal(`<h2 class="title">${x.dataset.name}</h2><p class="lead">A complete biography can be published here from the admin control centre when approved.</p>`));
 document.querySelector('.js-meeting')?.addEventListener('click',()=>toast('Meeting access request recorded. An invitation will be emailed after approval.'));
 document.querySelector('#registration')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const data={};form.querySelectorAll('input,select,textarea').forEach(el=>{const label=el.closest('.field')?.querySelector('label')?.textContent?.trim()||el.name||el.placeholder||'field';if((el.type==='radio'||el.type==='checkbox')&&!el.checked)return;(data[label]=el.value)});try{const r=await fetch('/api/public/registrations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Registration failed');toast(`Registration submitted. Reference: ${d.reference}`);form.reset()}catch(err){toast(err.message||'Registration failed')}});
 document.querySelector('#simpleForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const fields=[...form.querySelectorAll('input,textarea,select')];const data={};fields.forEach(el=>{const label=el.closest('.field')?.querySelector('label')?.textContent?.trim()||el.placeholder||el.name||'field';data[label]=el.value});const isContact=location.hash==='#contact';try{const r=await fetch('/api/public/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,formType:isContact?'website-contact':'website'})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Submission failed');toast('Thank you. Your submission has been received.');form.reset()}catch(err){toast(err.message||'Submission failed')}})
}function observe(){let o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');o.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(x=>o.observe(x))}
function registration(){return hero('Registration','Join the Shoto Point creative community.','Use this registration for community, learning, talent and event participation — not a production brief.')+`<section class="content"><form class="registration card reveal" id="registration"><div class="form-sections"><div class="form-section"><span>01</span><h3>Personal profile</h3><p>Your basic identity and contact details.</p><div class="form-grid"><div class="field"><label>First Name</label><input required name="first_name" placeholder="First name"></div><div class="field"><label>Last Name</label><input required name="last_name" placeholder="Last name"></div><div class="field"><label>Email address</label><input required type="email" name="email" placeholder="you@example.com"></div><div class="field"><label>Phone number</label><input required name="phone" placeholder="+234..."></div></div></div><div class="form-section"><span>02</span><h3>Choose your interest</h3><p>Tell us what brings you to Shoto Point.</p><select required><option value="">Select an interest</option><option>Training & classes</option><option>Talent & casting</option><option>Podcast / live event</option><option>Creative community</option></select></div><div class="form-section"><span>03</span><h3>Your experience</h3><p>Help us send the right opportunities.</p><div class="form-grid"><div class="field"><label>Experience level</label><select><option>Beginner</option><option>Intermediate</option><option>Professional</option></select></div><div class="field"><label>City / Location</label><input placeholder="Your city"></div></div></div><div class="form-section"><span>04</span><h3>Confirmation</h3><p>Choose how we may keep in touch.</p><label><input type="checkbox" required> I agree to be contacted about relevant Shoto Point opportunities.</label></div></div><br><button class="button button-gold" type="submit">Complete registration</button></form></section>`}
function projectStart(){return hero('Start a project','Let’s plan the production properly.','This detailed brief is specifically for clients commissioning a Shoto Point production.')+`<section class="content"><form class="registration card reveal" id="registration"><div class="form-sections"><div class="form-section"><span>01</span><h3>Project contact</h3><p>Who will lead this production conversation?</p><div class="form-grid"><div class="field"><label>First Name</label><input required name="first_name" placeholder="First name"></div><div class="field"><label>Last Name</label><input required name="last_name" placeholder="Last name"></div><div class="field"><label>Business / Organisation</label><input name="organisation" placeholder="Organisation name"></div><div class="field"><label>Work email</label><input required type="email" name="email" placeholder="you@example.com"></div></div></div><div class="form-section"><span>02</span><h3>Production requirements</h3><p>Define the format and the audience you want to reach.</p><div class="form-grid"><div class="field"><label>Service required</label><select required><option>Film Production</option><option>Television Production</option><option>Documentary</option><option>Photography</option><option>Commercials</option><option>Digital Media</option></select></div><div class="field"><label>Preferred delivery date</label><input type="date"></div><div class="field full"><label>Project objective</label><textarea required placeholder="What should this production achieve?"></textarea></div></div></div><div class="form-section"><span>03</span><h3>Scope & budget</h3><p>Early figures help the team propose the right scale.</p><div class="form-grid"><div class="field"><label>Estimated budget</label><select><option>To be discussed</option><option>Under ₦500,000</option><option>₦500,000 – ₦2,000,000</option><option>Above ₦2,000,000</option></select></div><div class="field"><label>Primary location</label><input placeholder="City or region"></div></div></div><div class="form-section"><span>04</span><h3>Review & submit</h3><p>Add links, references or extra notes for the production team.</p><textarea placeholder="Website, mood board, previous video links, or other notes."></textarea></div></div><br><button class="button button-gold" type="submit">Send production brief</button></form></section>`}
