function service(id){if(id==='film-production')return hero('Shoto Point Film Production','Cinematic stories with a life beyond the screen.','Development, production and release for films made with purpose.')+`<section class="content film-feature"><div class="wrap"><div class="film-diagram reveal"><div>IDEA<br><small>Discovery & script</small></div><i>→</i><div>SET<br><small>Production & crew</small></div><i>→</i><div>SCREEN<br><small>Post & delivery</small></div></div><div class="film-article reveal"><img src="${cover[0]}" alt="Shoto Point film production illustration"><div><h2 class="title">Film production at Shoto Point</h2><p>Shoto Point Film Production begins long before the camera rolls. We start by finding the emotional centre of a story, the question it asks, and the audience it can reach. This early work lets directors, writers, producers and clients share one clear creative direction before production begins.</p><p>On set, every department works as one connected production team. Camera, lighting, art, sound and performance are planned around the story rather than treated as separate tasks. That approach creates images with texture, energy and purpose.</p><p>We build practical plans around each project’s ambition. Whether the work is a short film, a feature, a branded story or a documentary-led production, our crew structure and schedule are designed to protect the quality of the final film.</p><p>Post-production gives the film its final rhythm. Editing, sound design, music, colour and titles are developed together so that every moment lands clearly and the visual language feels complete.</p><p>Most importantly, we think beyond delivery. A finished Shoto Point film is prepared for audiences, partners and platforms. We help shape the release materials and protected viewing experience that give a good story a longer future.</p></div></div><div class="section-head"><div><div class="eyebrow">Film library</div><h2 class="title">Watch the movies</h2></div></div><div class="media-grid">${media(3)}</div></div></section>`;let s=services.find(x=>x[0]===id)||services[0];return hero('Services',s[1].slice(3),s[3])+`<section class="content"><div class="wrap two-col"><article class="info-card card reveal"><div class="eyebrow">Our impact</div><h3>Made for the next audience.</h3><p class="lead">This service brings focused craft to projects that will inform, entertain and create opportunity long after release.</p><br><blockquote>“The team listened first, then made the message feel bigger than we imagined.” <small>— Production client</small></blockquote><br><a class="button button-gold" href="#register">Request this service</a></article><div>${media(1)}</div></div></section>`}
function aboutPage(){return hero('About Shoto Point','Stories. Vision. Production.','The people, ideas and visual culture behind Shoto Point Production.')+`<section class="content about-editorial"><div class="wrap"><article class="about-story reveal"><img src="${cover[1]}" alt="Creative team in production"><div><h2 class="title">A creative home for stories that matter.</h2><p>Shoto Point Production exists to help strong ideas find their clearest visual form. We bring writers, directors, producers, artists and partners together around stories that deserve time, attention and a meaningful audience.</p><p>Our work moves between film, television, documentary, photography and digital culture, but the foundation remains the same: listen carefully, plan intelligently and make each project feel alive.</p></div></article><article class="about-story reverse reveal"><img src="${cover[2]}" alt="Production creative process"><div><h2 class="title">Craft with a future.</h2><p>We are building a platform where creative people can grow, audiences can discover work with depth, and every production has room to travel further than its first release.</p><p>Shoto Point is a meeting point for vision and delivery. We value collaboration, protect the creative process and treat every frame, sound and page as an opportunity to connect.</p></div></article></div></section>`}
