function aboutPage(){return hero('About Shoto Point','Stories. Vision. Production.','The people, ideas and visual culture behind Shoto Point Production.')+`<section class="content"><div class="wrap"><div class="about-intro card reveal"><h2 class="title">Explore the work behind the point.</h2><p>Choose a production discipline to read its story, purpose and creative direction.</p></div><div class="grid about-service-grid">${services.map(s=>`<article class="service-card card reveal"><span class="number">${s[1].slice(0,2)}</span><div class="icon">${s[2]}</div><h3>${s[1].slice(3)}</h3><p>${s[3]}</p><br><a class="button button-gold" href="#about-${s[0]}">View story</a></article>`).join('')}</div></div></section>`}
function aboutService(id){if(id==='film-production')return aboutFilm();let s=services.find(x=>x[0]===id)||services[1];let name=s[1].slice(3);return hero(`About · ${name}`,`${name} with a purpose.`,'The story, creative direction and future impact of this Shoto Point discipline.')+`<section class="content"><article class="about-film-copy wrap reveal"><img class="about-service-image" src="${cover[services.indexOf(s)%3]}" alt="${name} illustration"><h2 class="title">${name} at Shoto Point</h2><p>At Shoto Point, ${name.toLowerCase()} begins with an understanding of people, place and purpose. We bring thoughtful creative planning to every brief so that the final work does more than fill a screen or a space.</p><p>Our team combines specialist craft with an open, collaborative process. Each decision is made to support the message, the audience and the lasting quality of the production.</p><p>We work with clients and creative partners from the first conversation through delivery, keeping the work clear, focused and practical at every stage.</p><p>The result is content that can inform, inspire and connect with audiences in the moment while staying useful beyond its first release.</p><p>Explore the rest of the About directory to discover how each Shoto Point discipline contributes to a stronger creative future.</p><br><a class="button button-outline" href="#about">Back to About</a></article></section>`}
